actions.script:
if (!ec.message.hasError()) {
    const rows = Array.from(sent.recipients || [])
    const went = rows.filter(row => row.state !== 'failed')
    ec.message.addMessage(ec.l10n.localize(sent.newIssue ? 'Quote issued and sent' : 'Quote sent') + ': '
            + went.map(row => row.name + (row.skipped ? ' (' + ec.l10n.localize('had it already') + ')' : '')).join(', '), 'success')
    for (const row of rows.filter(row => row.state === 'failed'))
        ec.message.addMessage(ec.l10n.localize('Not sent to') + ' ' + row.name + ': ' + (row.error || ''), 'warning')
}

if.script:
{
                const probed = ec.service.sync().name('mantle.order.SalesQuoteIssueServices.send#Quote').requireNewTransaction(true)
                        .parameters({orderId:orderId, orderRevision:issuesOut.orderRevision, previewOnly:'Y'}).call()
                if (probed != null) preview = Object.assign({}, preview || {}, probed)
            }

actions.script:
previewError = ec.message.getErrorsString() || ''
ec.message.clearErrors()
previewFound = canSend && !!preview?.recipients
recipientOptions = Array.from(issuesOut?.recipientOptions || []).map(row => ({
    value: row.partyId,
    label: row.name + ' · ' + (row.emailAddress || ec.l10n.localize('no email address'))
}))
previewRows = previewFound ? Array.from(preview.recipients).map(row => ({
    name: row.name,
    emailAddress: row.emailAddress || ec.l10n.localize('no email address: the send to them fails until one is added'),
    stateText: row.state === 'sent' ? ec.l10n.localize('Has it already') : row.state === 'failed' ? ec.l10n.localize('Failed: tried again')
        : row.state ? row.state : ec.l10n.localize('Will be sent')
})) : []
sendValues = previewFound ? {
    orderId: orderId,
    orderRevision: preview.orderRevision,
    recipientPartyIds: Array.from(preview.recipients).map(row => row.partyId),
    sendMode: preview.sendMode,
    subject: preview.subject,
    operationKey: 'send-' + ec.user.randomString(24)
} : {}
